(window.__APPSRC=window.__APPSRC||{})["xmvkq4zed--zze-sj-prepa-gyneco-j6-sf3"]="{\n \"app\": \"xmvkq4zed\",\n \"id\": \"zze-sj-prepa-gyneco-j6-sf3\",\n \"titre\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J6 (SF3)\",\n \"session\": \"J\",\n \"annee\": 2026,\n \"nq\": 40,\n \"nsuj\": 1,\n \"origines\": [\n  {\n   \"fichier\": \"prepa-de-2026/J6_Gyneco_SF3_corrige_explique.pdf\",\n   \"sha256\": \"f97f95c20e6638b9550be57c5067481265977d038a2b43f4721425d68371b3e8\"\n  }\n ],\n \"antennes\": [\n  {\n   \"name\": \"J DE PRÉPARATION AU D.E\",\n   \"slug\": \"j-preparation-de\",\n   \"session\": \"J\",\n   \"annee\": 2026,\n   \"existe\": true,\n   \"sujets\": [\n    {\n     \"name\": \"J Gynéco-obstétrique · Prépa D.E J6 (SF3)\",\n     \"slug\": \"prepa-gyneco-j6-sf3\",\n     \"pages\": \"\",\n     \"count\": 40,\n     \"session\": \"J\",\n     \"annee\": 2026,\n     \"matiere\": \"Gynéco-obstétrique\",\n     \"source\": \"J6_Gyneco_SF3_corrige_explique.pdf\",\n     \"questions\": [\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j6-sf3__0\",\n       \"num\": \"1\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le petit bassin osseux maternel comprend 3 parties qui sont : le détroit supérieur, le détroit moyen et le détroit inférieur\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le bassin osseux comprend deux orifices appelés détroits (supérieur et inférieur) et, entre les deux, l'excavation ; le détroit moyen n'est qu'un léger rétrécissement de l'excavation passant par les épines sciatiques. Les « 3 parties » sont donc : détroit supérieur, excavation, détroit inférieur. Remarque : Le cours de Soins obstétricaux 2e année présente « le détroit moyen ou excavation » comme un même plan ; la nuance porte sur le mot « détroit moyen ».\\n\\nSource : COURS GYNECO OBSTETRIQUE (1re année commune), Le bassin obstétrical, II.1 (p. 22-23)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J6 (SF3)\",\n       \"sourceFile\": \"J6_Gyneco_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j6-sf3__1\",\n       \"num\": \"2\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'ovogonie est un gamète femelle qui a 2 x 22 chromosomes\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"L'ovogonie n'est pas un gamète : c'est une cellule germinale souche qui donnera l'ovocyte puis l'ovule (le gamète). De plus, l'ovogonie est diploïde (46 chromosomes = 2 x 23), alors que le gamète est haploïde (23 chromosomes).\\n\\nSource : COURS GYNECO OBSTETRIQUE (1re année commune), Gamétogenèse, ovogenèse (p. 35-36) ; nombre de chromosomes (explication hors cours du projet)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J6 (SF3)\",\n       \"sourceFile\": \"J6_Gyneco_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j6-sf3__2\",\n       \"num\": \"3\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le repère de la présentation de la face est le menton.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La présentation de la face est une présentation céphalique totalement défléchie dont le repère est le menton (variétés MIDP, MIGA…).\\n\\nSource : COURS GYNECO OBSTETRIQUE (1re année commune), Présentations fœtales, II.4 (p. 59) ; COURS DE SOINS OBSTETRICAUX 2e année SF, 1-3 Présentation de la face\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J6 (SF3)\",\n       \"sourceFile\": \"J6_Gyneco_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j6-sf3__3\",\n       \"num\": \"4\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Après la naissance, les 1ères règles permettent de dater la puberté\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La correction nationale de la Prépa DE (les J) retient « Faux ». Le premier signe de la puberté chez la fille n'est pas l'apparition des règles mais le développement mammaire (vers 11 ans) ; les premières règles surviennent plus tard (vers 13 ans). On ne date donc pas le début de la puberté par les premières règles. Remarque : Le même cours écrit aussi que le début de la puberté est « marqué » par la survenue des premières règles ; la formulation « après la naissance » de l'énoncé est par ailleurs inhabituelle.\\n\\nSource : COURS GYNECO OBSTETRIQUE (1re année commune), Puberté féminine, II et III.1 (p. 13-14)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J6 (SF3)\",\n       \"sourceFile\": \"J6_Gyneco_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j6-sf3__4\",\n       \"num\": \"5\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Au cours de la grossesse normale, le poids de la gestante peut augmenter\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Au cours d'une grossesse normale, le poids augmente : environ 10 à 12 kg au total, soit 1 à 1,5 kg par mois, plus rapidement à partir du 5e mois.\\n\\nSource : COURS GYNECO OBSTETRIQUE (1re année commune), Modifications de l'organisme maternel, II.7 Le poids (p. 47) ; COURS DE SOINS OBSTETRICAUX 2e année SF, CPN 2e trimestre\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J6 (SF3)\",\n       \"sourceFile\": \"J6_Gyneco_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j6-sf3__5\",\n       \"num\": \"6\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les modifications physiologiques de l'organisme maternel au cours de la grossesse débutent avant la fécondation\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Les modifications physiologiques de l'organisme maternel sont la conséquence de la grossesse : elles débutent après la fécondation (et la nidation), sous l'effet des hormones de la grossesse, et non avant.\\n\\nSource : COURS GYNECO OBSTETRIQUE (1re année commune), Modifications de l'organisme de la femme au cours de la grossesse (p. 44)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J6 (SF3)\",\n       \"sourceFile\": \"J6_Gyneco_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j6-sf3__6\",\n       \"num\": \"7\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les 1ères règles s'appellent les ménarches\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Les premières règles portent bien le nom de « ménarche ».\\n\\nSource : COURS GYNECO OBSTETRIQUE (1re année commune), Puberté féminine, II. Physiologie (p. 13) ; DOCUMENT SSR L2 SF 2021 REVU, consultation PF (âge aux premières règles = ménarches)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J6 (SF3)\",\n       \"sourceFile\": \"J6_Gyneco_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j6-sf3__7\",\n       \"num\": \"8\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La prescription de fer est interdite au 1er trimestre de grossesse\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le fer n'est pas interdit au 1er trimestre : la supplémentation fer + acide folique peut débuter dès la 1re CPN (6e–12e semaine) selon les cours de soins obstétricaux et SONU. Remarque : Le cours GYNECO L2 IDE VERSION 2025 (anémie) conseille de commencer la prise de fer au début du 4e mois ; mais il ne parle pas d'interdiction.\\n\\nSource : COURS DE SOINS OBSTETRICAUX 2e année SF, Anémie et grossesse ; SONU L3, Anémie (p. 26)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J6 (SF3)\",\n       \"sourceFile\": \"J6_Gyneco_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j6-sf3__8\",\n       \"num\": \"9\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La sérologie de la toxoplasmose positive à Ig M témoigne d'une atteinte toxoplasmique\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Les IgM apparaissent dès le début de l'infestation et disparaissent vers 4 mois (« M comme Maladie ») : une sérologie toxoplasmique positive en IgM témoigne d'une infestation récente (atteinte toxoplasmique en cours).\\n\\nSource : Gynécologie-Obstétrique L3, Toxoplasmose et grossesse, IV. Examens sérologiques\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J6 (SF3)\",\n       \"sourceFile\": \"J6_Gyneco_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j6-sf3__9\",\n       \"num\": \"10\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Au 1er trimestre de grossesse, la présence des Ig G durant la sérologie de la rubéole signe une primo-infection de la rubéole qui est très grave\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Les IgG de la rubéole persistent des années (« G comme Guérison ») : IgM négatif + IgG positif signifie une infection ancienne, guérie (immunité). C'est la présence des IgM qui signe une primo-infection, tératogène.\\n\\nSource : Gynécologie-Obstétrique L3, Primo-infection de la rubéole et grossesse, IV/2\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J6 (SF3)\",\n       \"sourceFile\": \"J6_Gyneco_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j6-sf3__10\",\n       \"num\": \"11\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Au cours de la grossesse, l'association d'une TA égale à 15/10 cmHg, d'une protéinurie à 3 croix et d'une crise convulsive signe une pré-éclampsie très sévère\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"L'association HTA + protéinurie + crise convulsive ne signe pas une pré-éclampsie mais une éclampsie, complication de la pré-éclampsie. (Pré-éclampsie sévère : TA > 160/110 sans convulsion.)\\n\\nSource : COURS DE SOINS OBSTETRICAUX 2e année SF, HTA/éclampsie et grossesse, I et III.1 ; GYNECO L2 IDE VERSION 2025, éclampsie\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J6 (SF3)\",\n       \"sourceFile\": \"J6_Gyneco_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j6-sf3__11\",\n       \"num\": \"12\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"On parle d'hydramnios quand la quantité de liquide amniotique dépasse 2 litres dans les derniers mois de grossesse\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"L'hydramnios est une quantité élevée de liquide amniotique, supérieure à 2 litres à terme ; c'est une cause de hauteur utérine excessive.\\n\\nSource : Gynécologie-Obstétrique L3, causes des HU élevées (hydramnios)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J6 (SF3)\",\n       \"sourceFile\": \"J6_Gyneco_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j6-sf3__12\",\n       \"num\": \"13\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La survenue d'agitation, de confusion, ou de délire durant un paludisme à plasmodium falciparum au cours de la grossesse traduit automatiquement un paludisme grave\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Parmi les critères cliniques OMS du paludisme grave figurent les troubles de la conscience ou léthargie : agitation, confusion, délire, obnubilation, somnolence, coma. Leur survenue au cours d'un paludisme à P. falciparum signe un paludisme grave.\\n\\nSource : GYNECO L2 IDE VERSION 2025, Paludisme et grossesse, critères cliniques OMS ; Gynécologie-Obstétrique L3\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J6 (SF3)\",\n       \"sourceFile\": \"J6_Gyneco_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j6-sf3__13\",\n       \"num\": \"14\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Au cours de la grossesse, un taux d'hémoglobine égal à 10,2 g/100ml avec un CCMH = 26 picogrammes et un VGM = 70 µ3 évoquent une anémie hypochrome microcytaire.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Anémie de la grossesse : Hb < 11 g/100 ml (ici 10,2) ; hypochrome : CCMH < 27 pg (ici 26) ; microcytaire : VGM < 80 µ3 (ici 70). Le tableau correspond à une anémie hypochrome microcytaire (carence martiale).\\n\\nSource : GYNECO L2 IDE VERSION 2025, Anémie et grossesse, III/3-2 Examens complémentaires\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J6 (SF3)\",\n       \"sourceFile\": \"J6_Gyneco_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j6-sf3__14\",\n       \"num\": \"15\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Il est recommandé de donner une supplémentation de fer à une gestante ayant une hémoglobinose AS à partir du 2ème trimestre de grossesse pour éviter une anémie ferriprive\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La gestante AS (trait drépanocytaire, forme non majeure) reçoit la prévention habituelle de l'anémie : supplémentation en fer à partir du 2e trimestre (début du 4e mois), avec acide folique. Remarque : Pour les drépanocytoses majeures (SS…), le cours L3 recommande l'acide folique et de ne pas donner de fer (risque d'hémochromatose) ; cela ne concerne pas la forme AS.\\n\\nSource : GYNECO L2 IDE VERSION 2025, Anémie et grossesse, 4-1 : 2/ Traitement préventif\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J6 (SF3)\",\n       \"sourceFile\": \"J6_Gyneco_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j6-sf3__15\",\n       \"num\": \"16\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les signes suivants, relever celui ou ceux qui caractérise(nt) le placenta prævia marginal hémorragique dans sa forme typique :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A : Ménorragies indolores faites de sang rouge au 3ème trimestre de grossesse\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B : Métrorragies faites de sang rouge au 3ème trimestre de grossesse avec des contractions utérines\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C : Métrorragies indolores faites de sang noir au 3ème trimestre de grossesse\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D : Petit côté des membranes mesurant moins de 10 cm\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E : Petit côté des membranes mesurant moins de 9 cm\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"F : Métrorragies faites de sang rouge vif au 3ème trimestre de grossesse avec des\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"D. D : Petit côté des membranes mesurant moins de 10 cm ; E. E : Petit côté des membranes mesurant moins de 9 cm\",\n       \"answerLetters\": [\n        \"D\",\n        \"E\"\n       ],\n       \"explanation\": \"Après la délivrance, le signe qui confirme le placenta prævia est le petit côté des membranes mesurant moins de 10 cm ; un petit côté < 9 cm est a fortiori < 10 cm. Les autres options sont fausses : « ménorragies » (le saignement de la grossesse est une métrorragie), contractions utérines et sang noir évoquent plutôt l'HRP.\\n\\nSource : GYNECO L2 IDE VERSION 2025, Placenta prævia, IV-3\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J6 (SF3)\",\n       \"sourceFile\": \"J6_Gyneco_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j6-sf3__16\",\n       \"num\": \"17\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Relever la ou les manœuvre(s) à exécuter pour extraire la tête dernière retenue dans l'excavation pelvienne dans l'accouchement du siège.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A : Attitude de Vermelin\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B : Petite extraction du siège\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C : Grande extraction du siège\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D : Manœuvre de Bracht\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E : Manœuvre de Lovset\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"F : Manœuvre de Mauriceau\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"F. F : Manœuvre de Mauriceau\",\n       \"answerLetters\": [\n        \"F\"\n       ],\n       \"explanation\": \"Pour la tête dernière retenue dans l'excavation, on réalise la manœuvre de Mauriceau (doigts dans la bouche du fœtus, traction sur les épaules, fléchissement de la tête). Bracht sert pour une tête descendue en partie basse, Lovset pour le relèvement des bras.\\n\\nSource : SONU L3, Accouchement du siège, 3.2.2 (p. 72-73) ; Gynécologie-Obstétrique L3\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J6 (SF3)\",\n       \"sourceFile\": \"J6_Gyneco_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j6-sf3__17\",\n       \"num\": \"18\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le début du cycle menstruel commence toujours :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A : Au 1er jour de survenue des règles\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B : Au début des règles\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C : A la fin des règles\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D : A l'ovulation\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E : Au dernier jour précédant les règles\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"F : Au 1er jour des ménarches\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. A : Au 1er jour de survenue des règles ; B. B : Au début des règles\",\n       \"answerLetters\": [\n        \"A\",\n        \"B\"\n       ],\n       \"explanation\": \"Le cycle menstruel commence le 1er jour des règles (le 1er jour du saignement est le jour 1). « Au 1er jour de survenue des règles » et « au début des règles » disent la même chose.\\n\\nSource : COURS GYNECO OBSTETRIQUE (1re année commune), Cycle menstruel, I.1.1 (p. 26) ; DOCUMENT SSR L2 SF 2021 REVU, méthode du calendrier\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J6 (SF3)\",\n       \"sourceFile\": \"J6_Gyneco_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j6-sf3__18\",\n       \"num\": \"19\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans la présentation de la face, on sent au TV toujours :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A : La grande fontanelle du fœtus.\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B : La petite fontanelle du fœtus.\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C : Le front du fœtus.\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D : Le menton du fœtus.\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E : Les yeux du fœtus.\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"F : La bouche du fœtus.\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"F. F : La bouche du fœtus.\",\n       \"answerLetters\": [\n        \"F\"\n       ],\n       \"explanation\": \"Dans la présentation de la face, on ne perçoit pas de fontanelle au TV mais les éléments de la face : yeux, nez, bouche, menton. La bouche (orifice avec les gencives) est l'élément régulièrement perçu ; il faut faire attention aux yeux. Remarque : Le cours cite aussi le menton (repère de la présentation, option D non cochée) parmi les éléments perçus au TV.\\n\\nSource : COURS DE SOINS OBSTETRICAUX 2e année SF, 1-3 Présentation de la face ; COURS GYNECO OBSTETRIQUE (1re année commune)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J6 (SF3)\",\n       \"sourceFile\": \"J6_Gyneco_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j6-sf3__19\",\n       \"num\": \"20\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Après la réfection de l'épisiotomie, le soin ci-dessous ne doit pas ou les soins ci-dessous ne doivent pas être prodigués\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A : Faire bain de siège avec de l'eau froide\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B : Appliquer en permanence un linge mouillé sur la suture\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C : Assécher la suture\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D : Faire un pansement occlusif sur la suture\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E : Faire un pansement non occlusif sur la suture\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"F : Faire bain de siège avec de l'eau tiède ou chaude sur la suture\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. B : Appliquer en permanence un linge mouillé sur la suture ; D. D : Faire un pansement occlusif sur la suture ; F. F : Faire bain de siège avec de l'eau tiède ou chaude sur la suture\",\n       \"answerLetters\": [\n        \"B\",\n        \"D\",\n        \"F\"\n       ],\n       \"explanation\": \"Après réfection de l'épisiotomie, le périnée doit rester sec : toilette vulvaire biquotidienne, bien sécher, compresse stérile et garniture changée souvent. Sont donc à éviter le linge mouillé en permanence (B), le pansement occlusif (D, qui entretient l'humidité) et le bain de siège (F).\\n\\nSource : Gynécologie-Obstétrique L3, soins dans les suites de couches (épisiotomie) ; COURS GYNECO OBSTETRIQUE (1re année commune), suites de couches\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J6 (SF3)\",\n       \"sourceFile\": \"J6_Gyneco_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j6-sf3__20\",\n       \"num\": \"21\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les propositions suivantes, relever celle qui est fausse ou celles qui sont fausses\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A : Le cordon ombilical contient 3 vaisseaux\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B : Le fibrome utérin involue à la ménopause.\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C : Le fibrome utérin est cause de stérilité\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D : Le liquide amniotique est produit principalement par le fœtus\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E : A terme, le poids du placenta est égal au 1/6 du poids du fœtus.\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"F : Le cordon ombilical s'insère sur la face maternelle du placenta.\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"C. C : Le fibrome utérin est cause de stérilité ; F. F : Le cordon ombilical s'insère sur la face maternelle du placenta.\",\n       \"answerLetters\": [\n        \"C\",\n        \"F\"\n       ],\n       \"explanation\": \"C est fausse : le fibrome n'est pas synonyme de stérilité (la femme qui a un fibrome peut être enceinte ; il n'est cause de stérilité que dans certaines localisations). F est fausse : le cordon s'insère sur la face fœtale du placenta (insertion normalement centrale). Les autres sont vraies : cordon à 3 vaisseaux (2 artères, 1 veine), poids du placenta = 1/6 du poids de l'enfant.\\n\\nSource : Gynécologie-Obstétrique L3, Myome utérin et puerpéralité (NB) ; COURS DE SOINS OBSTETRICAUX 2e année SF, Examen du placenta\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J6 (SF3)\",\n       \"sourceFile\": \"J6_Gyneco_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j6-sf3__21\",\n       \"num\": \"22\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les facteurs suivants, relever celui qui est ou ceux qui sont classiquement des facteurs de risque de survenue du cancer du col utérin\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A : Cervicite virale\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B : Réalisation de façon régulière des examens de dépistage\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C : Partenaires sexuels multiples\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D : Nulliparité\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E : Premier accouchement après 30 ans\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"F : Antécédents de cancer du col chez la mère\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. A : Cervicite virale ; C. C : Partenaires sexuels multiples\",\n       \"answerLetters\": [\n        \"A\",\n        \"C\"\n       ],\n       \"explanation\": \"Le cancer du col est viro-induit (HPV 16 et 18, HSV2) : la cervicite virale et la multiplicité des partenaires sexuels sont des facteurs de risque classiques. Le dépistage régulier est au contraire protecteur ; le cours cite la grande multiparité avec 1er enfant avant 20 ans, pas la nulliparité ni le 1er accouchement après 30 ans.\\n\\nSource : GYNECO L2 IDE VERSION 2025, Cancer du col utérin, 3. Facteurs de risque\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J6 (SF3)\",\n       \"sourceFile\": \"J6_Gyneco_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j6-sf3__22\",\n       \"num\": \"23\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les signes suivants évoquent une grossesse môlaire :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A : Métrorragies spontanées faites de sang rouge au cours du 1er trimestre de grossesse\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B : Métrorragies spontanées de sang noir au cours du 1er trimestre de grossesse\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C : Métrorragies provoquées de sang rouge au cours du 1er trimestre de grossesse\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D : Sialorrhée et vomissements au cours du 1er trimestre de grossesse associés à un placenta ressemblant aux frais de grenouille\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E : Aménorrhée\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"F : Ménorragie\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. A : Métrorragies spontanées faites de sang rouge au cours du 1er trimestre de grossesse ; D. D : Sialorrhée et vomissements au cours du 1er trimestre de grossesse associés à un placenta ressemblant aux frais de grenouille\",\n       \"answerLetters\": [\n        \"A\",\n        \"D\"\n       ],\n       \"explanation\": \"La môle hydatiforme donne des métrorragies du 1er trimestre spontanées, répétées, de sang rouge, avec sialorrhée, nausées et vomissements ; le produit expulsé a un aspect de vésicules en « grappe de raisin » ou « frais de grenouille ». Remarque : Un tableau du cours L3 (texte OCR) mentionne « métrorragie sang noir » pour la môle ; le cours IDE parle bien de sang rouge.\\n\\nSource : GYNECO L2 IDE VERSION 2025, Grossesse môlaire, IV-1 et III\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J6 (SF3)\",\n       \"sourceFile\": \"J6_Gyneco_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j6-sf3__23\",\n       \"num\": \"24\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"1er CAS CLINIQUE. Ce jour à 5 heures, Mme B.B.B. 30 ans, G6, P5, non obèse, se présente à la maternité pour des contractions utérines sur grossesse à terme. Le travail d'accouchement a commencé à 4 h. La hauteur utérine = 36 cm. Température = 36°,9 C. Le col est dilaté à 5 cm. Le taux d'hémoglobine = 10 g/100ml. Grâce à vos soins appropriés, Mme B.B.B. donne naissance à 5 heures 20 minutes d'une fille pesant 4000 grammes, à la naissance, celle-ci ne crie pas et ne respire pas. La délivrance est faite à 5 heures 30 minutes sans GATPA par TCC. Mme B.B.B. risque de saigner abondamment et mourir.\",\n       \"text\": \"Parmi les propositions suivantes, relever le geste ou les gestes à exécuter vis-à-vis de ce nouveau-né :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A : Massage cardiaque externe\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B : Demander de l'aide et expliquer doucement à la mère les gestes à faire.\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C : Couper aussitôt le cordon ombilical avant 1 mn de vie.\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D : Bien placer le nouveau-né en décubitus dorsal, le cou en extension modérée.\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E : Libérer les voies aériennes.\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"F : Administration des médicaments pour faire respirer ce nouveau-né\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. B : Demander de l'aide et expliquer doucement à la mère les gestes à faire. ; D. D : Bien placer le nouveau-né en décubitus dorsal, le cou en extension modérée. ; E. E : Libérer les voies aériennes.\",\n       \"answerLetters\": [\n        \"B\",\n        \"D\",\n        \"E\"\n       ],\n       \"explanation\": \"Nouveau-né qui ne crie pas et ne respire pas : appeler à l'aide (et informer la mère), installer le nouveau-né sur le dos, la tête en légère extension, et libérer les voies aériennes avant de ventiler. Pas de massage cardiaque d'emblée ni de médicaments pour le faire respirer.\\n\\nSource : COURS DE SOINS OBSTETRICAUX 2e année SF, Mécanisme de l'accouchement (si le bébé ne respire pas dans les 30 s, appeler à l'aide) ; COURS GYNECO OBSTETRIQUE (1re année commune), soins au nouveau-né (désobstruction des voies aériennes)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J6 (SF3)\",\n       \"sourceFile\": \"J6_Gyneco_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j6-sf3__24\",\n       \"num\": \"25\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"1er CAS CLINIQUE. Ce jour à 5 heures, Mme B.B.B. 30 ans, G6, P5, non obèse, se présente à la maternité pour des contractions utérines sur grossesse à terme. Le travail d'accouchement a commencé à 4 h. La hauteur utérine = 36 cm. Température = 36°,9 C. Le col est dilaté à 5 cm. Le taux d'hémoglobine = 10 g/100ml. Grâce à vos soins appropriés, Mme B.B.B. donne naissance à 5 heures 20 minutes d'une fille pesant 4000 grammes, à la naissance, celle-ci ne crie pas et ne respire pas. La délivrance est faite à 5 heures 30 minutes sans GATPA par TCC. Mme B.B.B. risque de saigner abondamment et mourir.\",\n       \"text\": \"Grâce à ces gestes correctement exécutés, ce nouveau-né a une ventilation spontanée efficace, durable et tout va très bien. Néanmoins, vous décidez de surveiller l'accouchée et son nouveau-né. Entre 5 h30mn et 7 h30 mn, chez la mère vous allez surveiller le ou les paramètres suivants\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A : Les lochies pour rechercher une endométrite du post-partum.\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B : La TA.\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C : Le pouls.\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D : L'écoulement vulvaire pour rechercher un saignement anormal.\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E : Le globe de sécurité.\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"F : Les conjonctives pour rechercher un ictère.\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. B : La TA. ; C. C : Le pouls. ; D. D : L'écoulement vulvaire pour rechercher un saignement anormal. ; E. E : Le globe de sécurité.\",\n       \"answerLetters\": [\n        \"B\",\n        \"C\",\n        \"D\",\n        \"E\"\n       ],\n       \"explanation\": \"Dans les 2 heures qui suivent l'accouchement, on surveille la TA, le pouls, l'écoulement vulvaire (saignement) et le globe de sécurité utérin, pour dépister une hémorragie. L'endométrite (lochies) et l'ictère ne se recherchent pas à ce moment.\\n\\nSource : COURS DE SOINS OBSTETRICAUX 2e année SF, Soins à l'accouchée, 1-2 Surveillance ; COURS GYNECO OBSTETRIQUE (1re année commune), suites de couches, III.1.1\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J6 (SF3)\",\n       \"sourceFile\": \"J6_Gyneco_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j6-sf3__25\",\n       \"num\": \"26\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"1er CAS CLINIQUE. Ce jour à 5 heures, Mme B.B.B. 30 ans, G6, P5, non obèse, se présente à la maternité pour des contractions utérines sur grossesse à terme. Le travail d'accouchement a commencé à 4 h. La hauteur utérine = 36 cm. Température = 36°,9 C. Le col est dilaté à 5 cm. Le taux d'hémoglobine = 10 g/100ml. Grâce à vos soins appropriés, Mme B.B.B. donne naissance à 5 heures 20 minutes d'une fille pesant 4000 grammes, à la naissance, celle-ci ne crie pas et ne respire pas. La délivrance est faite à 5 heures 30 minutes sans GATPA par TCC. Mme B.B.B. risque de saigner abondamment et mourir.\",\n       \"text\": \"En dehors de tout élément anormal, la fréquence normale de cette surveillance entre 6 h30mn et 7h30 mn est : (Relever la fréquence correcte)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A : Toutes les 10 mn\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B : Toutes les 15 mn\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C : Toutes les 30 mn\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D : Toutes les 40 mn\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E : Toutes les 60 mn\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"F : Toutes les 20 mn\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. C : Toutes les 30 mn\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"La correction nationale de la Prépa DE (les J) retient une surveillance toutes les 30 minutes pendant les 2 premières heures du post-partum, comme le cours de 1re année. Remarque : Le cours de Soins obstétricaux et le chapitre « soins à l'accouchée » du cours de 1re année donnent une autre périodicité : toutes les 15 min pendant les 2 premières heures, puis toutes les 30 min pendant la 3e heure.\\n\\nSource : COURS GYNECO OBSTETRIQUE (1re année commune), Suites de couches normales, III.1.1 (« toutes les 30 mn pendant 2 heures »)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J6 (SF3)\",\n       \"sourceFile\": \"J6_Gyneco_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j6-sf3__26\",\n       \"num\": \"27\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"1er CAS CLINIQUE. Ce jour à 5 heures, Mme B.B.B. 30 ans, G6, P5, non obèse, se présente à la maternité pour des contractions utérines sur grossesse à terme. Le travail d'accouchement a commencé à 4 h. La hauteur utérine = 36 cm. Température = 36°,9 C. Le col est dilaté à 5 cm. Le taux d'hémoglobine = 10 g/100ml. Grâce à vos soins appropriés, Mme B.B.B. donne naissance à 5 heures 20 minutes d'une fille pesant 4000 grammes, à la naissance, celle-ci ne crie pas et ne respire pas. La délivrance est faite à 5 heures 30 minutes sans GATPA par TCC. Mme B.B.B. risque de saigner abondamment et mourir.\",\n       \"text\": \"A 6h, Mme BBB a saigné 100ml par voie vaginale ; elle transpire abondamment, sa TA = 6/4 cmHg, son pouls = 120/mn, ses conjonctives sont blanches et pas d'ictère, le périnée est intact. Selon vous, de quoi souffre Mme BBB ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A : Hémorragie du Post Partum\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B : Hémorragie du Post Partum immédiat\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C : Hémorragie du Post Partum tardif\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D : Hémorragie du Post Partum immédiat par atonie utérine\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E : Hémorragie du Post Partum immédiat par trouble de la coagulation\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"F : Hémorragie du Post Partum immédiat par déchirure périnéale\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. A : Hémorragie du Post Partum ; B. B : Hémorragie du Post Partum immédiat ; D. D : Hémorragie du Post Partum immédiat par atonie utérine\",\n       \"answerLetters\": [\n        \"A\",\n        \"B\",\n        \"D\"\n       ],\n       \"explanation\": \"Saignement survenu 30 minutes après la délivrance (moins de 24 h) avec signes de choc (TA 6/4, pouls 120, sueurs, conjonctives pâles) : hémorragie du post-partum immédiat. Le périnée étant intact et la délivrance faite sans GATPA, la cause la plus probable est l'atonie utérine (70 % des HPPI). Remarque : Le seuil de définition de l'HPP est de 500 ml ; ici 100 ml seulement, mais le cours rappelle qu'une perte minime peut être dramatique chez une femme anémiée (Hb 10 g/100 ml).\\n\\nSource : GYNECO L2 IDE VERSION 2025, HPPI, IV. Causes (4 T) ; COURS DE SOINS OBSTETRICAUX 2e année SF, HPP\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J6 (SF3)\",\n       \"sourceFile\": \"J6_Gyneco_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j6-sf3__27\",\n       \"num\": \"28\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"1er CAS CLINIQUE. Ce jour à 5 heures, Mme B.B.B. 30 ans, G6, P5, non obèse, se présente à la maternité pour des contractions utérines sur grossesse à terme. Le travail d'accouchement a commencé à 4 h. La hauteur utérine = 36 cm. Température = 36°,9 C. Le col est dilaté à 5 cm. Le taux d'hémoglobine = 10 g/100ml. Grâce à vos soins appropriés, Mme B.B.B. donne naissance à 5 heures 20 minutes d'une fille pesant 4000 grammes, à la naissance, celle-ci ne crie pas et ne respire pas. La délivrance est faite à 5 heures 30 minutes sans GATPA par TCC. Mme B.B.B. risque de saigner abondamment et mourir.\",\n       \"text\": \"Parmi les propositions suivantes, relever, chez Mme BBB, le ou les facteurs de risque de survenue de cette pathologie.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A : Mme B.B.B. admise à 5 heures et le col est dilaté à 5 cm\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B : Taux d'hémoglobine = = 10 g/100ml\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C : Accouchement d'un garçon pesant 4000 grammes\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D : Hauteur utérine = 36 cm\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E : Début de travail à 4 h et Mme B.B.B. donne naissance à 5 heures 20 minutes\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"F : Hauteur utérine=37 cm\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"D. D : Hauteur utérine = 36 cm ; E. E : Début de travail à 4 h et Mme B.B.B. donne naissance à 5 heures 20 minutes\",\n       \"answerLetters\": [\n        \"D\",\n        \"E\"\n       ],\n       \"explanation\": \"Facteurs de risque de l'atonie utérine : surdistension utérine (HU excessive à 36 cm, gros fœtus de 4000 g) et travail d'accouchement trop rapide (début à 4 h, naissance à 5 h 20). L'option C est fausse car l'enfant est une fille ; la Hb à 10 g est un facteur d'aggravation.\\n\\nSource : GYNECO L2 IDE VERSION 2025, HPPI, facteurs de risque de l'atonie utérine\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J6 (SF3)\",\n       \"sourceFile\": \"J6_Gyneco_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j6-sf3__28\",\n       \"num\": \"29\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"1er CAS CLINIQUE. Ce jour à 5 heures, Mme B.B.B. 30 ans, G6, P5, non obèse, se présente à la maternité pour des contractions utérines sur grossesse à terme. Le travail d'accouchement a commencé à 4 h. La hauteur utérine = 36 cm. Température = 36°,9 C. Le col est dilaté à 5 cm. Le taux d'hémoglobine = 10 g/100ml. Grâce à vos soins appropriés, Mme B.B.B. donne naissance à 5 heures 20 minutes d'une fille pesant 4000 grammes, à la naissance, celle-ci ne crie pas et ne respire pas. La délivrance est faite à 5 heures 30 minutes sans GATPA par TCC. Mme B.B.B. risque de saigner abondamment et mourir.\",\n       \"text\": \"Parmi les propositions suivantes, relever, chez Mme BBB, le ou les facteurs de risque d'aggravation de cette pathologie.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A : Mme B.B.B. admise à 5 heures et le col est dilaté à 5 cm\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B : Mme B.B.B., non obèse et paroi abdominale mince\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C : Accouchement d'un garçon pesant 4000 grammes\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D : Hauteur utérine à 36 cm\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E : Début de travail à 4 h et Mme B.B.B. donne naissance à 5 heures 20 minutes\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"F : Taux d'hémoglobine = 10 g/100ml\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"F. F : Taux d'hémoglobine = 10 g/100ml\",\n       \"answerLetters\": [\n        \"F\"\n       ],\n       \"explanation\": \"L'anémie antérieure non compensée (Hb 10 g/100 ml) est l'un des deux « ennemis » qui aggravent le pronostic de l'HPPI, avec le retard de prise en charge.\\n\\nSource : Gynécologie-Obstétrique L3, HPPI (« l'anémie antérieure non compensée »)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J6 (SF3)\",\n       \"sourceFile\": \"J6_Gyneco_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j6-sf3__29\",\n       \"num\": \"30\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"1er CAS CLINIQUE. Ce jour à 5 heures, Mme B.B.B. 30 ans, G6, P5, non obèse, se présente à la maternité pour des contractions utérines sur grossesse à terme. Le travail d'accouchement a commencé à 4 h. La hauteur utérine = 36 cm. Température = 36°,9 C. Le col est dilaté à 5 cm. Le taux d'hémoglobine = 10 g/100ml. Grâce à vos soins appropriés, Mme B.B.B. donne naissance à 5 heures 20 minutes d'une fille pesant 4000 grammes, à la naissance, celle-ci ne crie pas et ne respire pas. La délivrance est faite à 5 heures 30 minutes sans GATPA par TCC. Mme B.B.B. risque de saigner abondamment et mourir.\",\n       \"text\": \"Le premier geste à exécuter pour arrêter ce saignement par voie vaginale chez Mme BBB est : (Relever la réponse exacte parmi les propositions suivantes).\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A : Révision utérine suivie de délivrance artificielle.\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B : Perfusion intraveineuse de 5 unités de syntocinon*(ocytocine).\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C : Révision utérine.\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D : Perfusion intraveineuse d'antibiotiques et de 5 unités de syntocinon*(ocytocine).\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E : Délivrance artificielle suivie de révision utérine.\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"F : Délivrance artificielle.\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. C : Révision utérine.\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"La délivrance est déjà faite : on ne fait pas de délivrance artificielle. Devant une HPP par atonie, la sage-femme pratique la révision utérine (vacuité et intégrité de l'utérus), associée au massage utérin et à l'ocytocine en perfusion.\\n\\nSource : COURS DE SOINS OBSTETRICAUX 2e année SF, CAT devant les HPP, 3-1-3 Atonie utérine\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J6 (SF3)\",\n       \"sourceFile\": \"J6_Gyneco_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j6-sf3__30\",\n       \"num\": \"31\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"2ème CAS CLINIQUE. Vous avez reçu, ce jour, à 6 heures, dans la maternité rurale où vous exercez, Mme C.C.C. pour des contractions utérines sur grossesse à terme. Mme C.C.C. a 27 ans, 4ème geste, 3ème pare, sans antécédent particulier. Elle a 3 contractions utérines en 10 minutes, chaque contraction utérine dure 40 secondes ; le col utérin est dilaté à 5 cm, les 2 pieds sont perçus dans l'aire de dilatation cervicale, la variété de présentation est en S.I.D.A. et le bassin est normal.\",\n       \"text\": \"Ici, il s'agit d'une : (Relever la réponse exacte ou les réponses exactes parmi les propositions suivantes)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A : Présentation du sommet\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B : Présentation du siège\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C : Présentation du siège décomplété\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D : Présentation de la face tournée vers le sacrum\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E : Présentation du siège complet\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"F : Présentation céphalique avec procidence des 2 pieds.\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"E. E : Présentation du siège complet\",\n       \"answerLetters\": [\n        \"E\"\n       ],\n       \"explanation\": \"Les 2 pieds sont perçus dans l'aire de dilatation : fesses + pieds = siège complet (fœtus « assis en tailleur »). Dans le siège décomplété, on ne perçoit que les fesses.\\n\\nSource : SONU L3, Accouchement du siège, 2.1 (p. 68) ; COURS DE SOINS OBSTETRICAUX 2e année SF, Présentation du siège\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J6 (SF3)\",\n       \"sourceFile\": \"J6_Gyneco_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j6-sf3__31\",\n       \"num\": \"32\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"2ème CAS CLINIQUE. Vous avez reçu, ce jour, à 6 heures, dans la maternité rurale où vous exercez, Mme C.C.C. pour des contractions utérines sur grossesse à terme. Mme C.C.C. a 27 ans, 4ème geste, 3ème pare, sans antécédent particulier. Elle a 3 contractions utérines en 10 minutes, chaque contraction utérine dure 40 secondes ; le col utérin est dilaté à 5 cm, les 2 pieds sont perçus dans l'aire de dilatation cervicale, la variété de présentation est en S.I.D.A. et le bassin est normal.\",\n       \"text\": \"Ici, le repère de cette présentation est : (Relever la réponse exacte parmi les propositions suivantes)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A : L'occiput du fœtus\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B : La racine du nez fœtal\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C : Le sacrum du fœtus\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D : La petite fontanelle du fœtus\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E : Le menton du fœtus\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"F : Le sacrum de la parturiente\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. C : Le sacrum du fœtus\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Le repère de la présentation du siège est le sacrum du fœtus (d'où la variété S.I.D.A. = sacro-iliaque droite antérieure).\\n\\nSource : COURS DE SOINS OBSTETRICAUX 2e année SF, Présentation du siège ; COURS GYNECO OBSTETRIQUE (1re année commune)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J6 (SF3)\",\n       \"sourceFile\": \"J6_Gyneco_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j6-sf3__32\",\n       \"num\": \"33\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"2ème CAS CLINIQUE. Vous avez reçu, ce jour, à 6 heures, dans la maternité rurale où vous exercez, Mme C.C.C. pour des contractions utérines sur grossesse à terme. Mme C.C.C. a 27 ans, 4ème geste, 3ème pare, sans antécédent particulier. Elle a 3 contractions utérines en 10 minutes, chaque contraction utérine dure 40 secondes ; le col utérin est dilaté à 5 cm, les 2 pieds sont perçus dans l'aire de dilatation cervicale, la variété de présentation est en S.I.D.A. et le bassin est normal.\",\n       \"text\": \"Parmi les propositions de phrases suivantes, relever la phrase qui est vraie ou les phrases qui sont vraies concernant le cas de Mme C.C.C.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A : Dès la fin de mon examen, je commence à remplir le partographe modifié de l'O.M.S.\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B : Dès la fin de mon examen, je ne remplis pas le partographe modifié de l'O.M.S., car l'état de la poche des eaux n'est pas précisé\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C : Dès la fin de mon examen, je ne commence pas à remplir le partographe modifié de l'O.M.S car il ne s'agit pas d'une présentation eutocique\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D : Dès la fin de mon examen, je ne remplis pas le partographe modifié de l'O.M.S.\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E : Dès la fin de mon examen, je ne remplis pas le partographe modifié de l'O.M.S., car il s'agit d'une présentation en S.I.D.A.\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"F : Dès la fin de mon examen, je ne remplis pas le partographe modifié de l'O.M.S., car je suis en périphérie\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. A : Dès la fin de mon examen, je commence à remplir le partographe modifié de l'O.M.S.\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le col est à 5 cm avec 3 contractions de 40 s en 10 min : la parturiente est en phase active. Le partographe doit être démarré dès le début de la phase active, quelle que soit la présentation : « tout travail doit être surveillé par le partographe ».\\n\\nSource : COURS DE SOINS OBSTETRICAUX 2e année SF, Partographe (pratiques à encourager, conclusion) ; SONU L3, siège : remplir le partographe\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J6 (SF3)\",\n       \"sourceFile\": \"J6_Gyneco_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j6-sf3__33\",\n       \"num\": \"34\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"2ème CAS CLINIQUE. Vous avez reçu, ce jour, à 6 heures, dans la maternité rurale où vous exercez, Mme C.C.C. pour des contractions utérines sur grossesse à terme. Mme C.C.C. a 27 ans, 4ème geste, 3ème pare, sans antécédent particulier. Elle a 3 contractions utérines en 10 minutes, chaque contraction utérine dure 40 secondes ; le col utérin est dilaté à 5 cm, les 2 pieds sont perçus dans l'aire de dilatation cervicale, la variété de présentation est en S.I.D.A. et le bassin est normal.\",\n       \"text\": \"Concernant Mme C.C.C., l'une des phrases suivantes est synonyme d'organisation de son transfert ou les phrases suivantes sont synonymes d'organisation de son transfert depuis son admission à la maternité. (Relever cette phrase parmi les propositions suivantes)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A : Poche des eaux intacte\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B : Rupture tempestive des membranes\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C : Rupture précoce des membranes à 5 cm.\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D : Bruits du cœur fœtal=140/mn, réguliers et liquide amniotique méconial\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E : Rupture prématurée des membranes\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"F : Rupture des membranes à 10 cm de dilatation cervicale\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"C. C : Rupture précoce des membranes à 5 cm. ; E. E : Rupture prématurée des membranes\",\n       \"answerLetters\": [\n        \"C\",\n        \"E\"\n       ],\n       \"explanation\": \"Dans une maternité rurale (périphérie), le siège doit être référé vers un centre SONUC. Une rupture des membranes (précoce à 5 cm ou prématurée) dans un siège expose à la procidence du cordon, facteur en faveur d'une césarienne : c'est un motif d'organiser le transfert. La poche des eaux doit au contraire être respectée jusqu'à dilatation complète.\\n\\nSource : SONU L3, Accouchement du siège, 2.2 et IV ; COURS DE SOINS OBSTETRICAUX 2e année SF, Présentation du siège (CAT en périphérie)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J6 (SF3)\",\n       \"sourceFile\": \"J6_Gyneco_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j6-sf3__34\",\n       \"num\": \"35\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"2ème CAS CLINIQUE. Vous avez reçu, ce jour, à 6 heures, dans la maternité rurale où vous exercez, Mme C.C.C. pour des contractions utérines sur grossesse à terme. Mme C.C.C. a 27 ans, 4ème geste, 3ème pare, sans antécédent particulier. Elle a 3 contractions utérines en 10 minutes, chaque contraction utérine dure 40 secondes ; le col utérin est dilaté à 5 cm, les 2 pieds sont perçus dans l'aire de dilatation cervicale, la variété de présentation est en S.I.D.A. et le bassin est normal.\",\n       \"text\": \"Indiquer le geste ou les gestes à exécuter chez Mme C.C.C. dès que le col utérin est dilaté à 10 cm parmi les propositions suivantes :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A : Pratiquer une large épisiotomie\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B : Perfusion intraveineuse de 5 unités de syntocinon* (ocytocine) pour renforcer les contractions utérines et empêcher le relèvement des bras du fœtus durant le TV.\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C : Perfusion intraveineuse de 5 unités de syntocinon*(ocytocine) pour dilater le col utérin\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D : Faire une grande extraction du siège en l'absence de souffrance fœtale aigüe\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E : Surtout ne pas rompre la poche des eaux\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"F : Injection en intramusculaire de 10 unités de syntocinon*(ocytocine)\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. B : Perfusion intraveineuse de 5 unités de syntocinon* (ocytocine) pour renforcer les contractions utérines et empêcher le relèvement des bras du fœtus durant le TV.\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"À dilatation complète d'un siège, on met 5 UI d'ocytocine dans la perfusion pour maintenir de bonnes contractions utérines (et éviter le relèvement des bras) ; on rompt les membranes quand la parturiente est prête à pousser. L'épisiotomie se fait plus tard, quand le siège appuie sur le périnée.\\n\\nSource : SONU L3, Accouchement du siège, 2.2 (p. 69)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J6 (SF3)\",\n       \"sourceFile\": \"J6_Gyneco_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j6-sf3__35\",\n       \"num\": \"36\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"2ème CAS CLINIQUE. Vous avez reçu, ce jour, à 6 heures, dans la maternité rurale où vous exercez, Mme C.C.C. pour des contractions utérines sur grossesse à terme. Mme C.C.C. a 27 ans, 4ème geste, 3ème pare, sans antécédent particulier. Elle a 3 contractions utérines en 10 minutes, chaque contraction utérine dure 40 secondes ; le col utérin est dilaté à 5 cm, les 2 pieds sont perçus dans l'aire de dilatation cervicale, la variété de présentation est en S.I.D.A. et le bassin est normal.\",\n       \"text\": \"A un moment donné, vous décidez de pratiquer une large épisiotomie. Indiquer le moment idéal pour réaliser ce geste en relevant la proposition exacte parmi les phrases ci-dessous :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A : Quand la tête fœtale est visible durant une contraction utérine\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B : Quand la tête fœtale est visible en dehors d'une contraction utérine\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C : Quand l'anus fœtal est dilaté à 2-3 cm durant une contraction utérine\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D : Quand l'anus maternel est dilaté à 2-3 cm durant une contraction utérine\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E : Dès le siège prend contact avec le périnée maternel ou quand le siège fait bomber le périnée et la hanche antérieure commence à se dégager ou quand on voit l'anus fœtal durant une contraction utérine.\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"F : Quand le col utérin est dilaté à 10 cm durant une contraction utérine\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"E. E : Dès le siège prend contact avec le périnée maternel ou quand le siège fait bomber le périnée et la hanche antérieure commence à se dégager ou quand on voit l'anus fœtal durant une contraction utérine.\",\n       \"answerLetters\": [\n        \"E\"\n       ],\n       \"explanation\": \"L'épisiotomie large se fait dès que le siège appuie sur le périnée (le fait bomber), quand la hanche antérieure commence à se dégager, c'est-à-dire quand on voit l'anus du fœtus.\\n\\nSource : Gynécologie-Obstétrique L3, Accouchement du siège ; SONU L3, III (p. 69)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J6 (SF3)\",\n       \"sourceFile\": \"J6_Gyneco_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j6-sf3__36\",\n       \"num\": \"37\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"2ème CAS CLINIQUE. Vous avez reçu, ce jour, à 6 heures, dans la maternité rurale où vous exercez, Mme C.C.C. pour des contractions utérines sur grossesse à terme. Mme C.C.C. a 27 ans, 4ème geste, 3ème pare, sans antécédent particulier. Elle a 3 contractions utérines en 10 minutes, chaque contraction utérine dure 40 secondes ; le col utérin est dilaté à 5 cm, les 2 pieds sont perçus dans l'aire de dilatation cervicale, la variété de présentation est en S.I.D.A. et le bassin est normal.\",\n       \"text\": \"Parmi les gestes suivants, relever celui qui doit être exécuté ou ceux qui doivent être exécutés durant la réparation d'une épisiotomie :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A : Suturer tous les 3 plans avec du nylon n°1\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B : Suturer tous les 3 plans avec du nylon n°2\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C : Suturer tous les 3 plans avec du fil non résorbable non serti n°1\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D : Commencer la suture toujours de la profondeur du vagin pour venir vers la vulve.\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E : Ne pas suturer l'angle supérieur de l'incision vaginale\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"F : Réaliser la suture en un seul plan\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. D : Commencer la suture toujours de la profondeur du vagin pour venir vers la vulve.\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"La réfection de l'épisiotomie se fait en 3 plans successifs, au fil résorbable ; le plan vaginal commence toujours par l'angle supérieur de l'incision (profondeur du vagin) pour descendre vers la vulve (berges hyménales).\\n\\nSource : SONU L3, Épisiotomie et sa réfection, 5.1.5 Réparation (p. 63-64)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J6 (SF3)\",\n       \"sourceFile\": \"J6_Gyneco_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j6-sf3__37\",\n       \"num\": \"38\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"2ème CAS CLINIQUE. Vous avez reçu, ce jour, à 6 heures, dans la maternité rurale où vous exercez, Mme C.C.C. pour des contractions utérines sur grossesse à terme. Mme C.C.C. a 27 ans, 4ème geste, 3ème pare, sans antécédent particulier. Elle a 3 contractions utérines en 10 minutes, chaque contraction utérine dure 40 secondes ; le col utérin est dilaté à 5 cm, les 2 pieds sont perçus dans l'aire de dilatation cervicale, la variété de présentation est en S.I.D.A. et le bassin est normal.\",\n       \"text\": \"Au cours de l'expulsion de ce fœtus en présentation du siège, il vous est recommandé de terminer rapidement cette expulsion par une manœuvre, malgré l'absence de toute dystocie. Laquelle parmi les propositions suivantes ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A : Je pratique la manœuvre de Mauriceau dès que je vois la pointe des omoplates du fœtus\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B : Je pratique la manœuvre de Bracht dès que je vois la pointe des omoplates du fœtus\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C : Je pratique systématiquement la manœuvre de Lovset\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D : Je pratique la manœuvre de Mauriceau dès que je vois les oreilles du fœtus\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E : J'adopte l'attitude de Vermelin\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"F : Je pratique la manœuvre de Bracht dès que je vois les oreilles du fœtus\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. B : Je pratique la manœuvre de Bracht dès que je vois la pointe des omoplates du fœtus\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"En Côte d'Ivoire, l'accoucheur réalise systématiquement la manœuvre de Bracht dès que les pointes des omoplates apparaissent à la vulve ; l'attitude de Vermelin n'est pas recommandée.\\n\\nSource : Gynécologie-Obstétrique L3, Accouchement du siège (manœuvre de Bracht)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J6 (SF3)\",\n       \"sourceFile\": \"J6_Gyneco_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j6-sf3__38\",\n       \"num\": \"39\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"2ème CAS CLINIQUE. Vous avez reçu, ce jour, à 6 heures, dans la maternité rurale où vous exercez, Mme C.C.C. pour des contractions utérines sur grossesse à terme. Mme C.C.C. a 27 ans, 4ème geste, 3ème pare, sans antécédent particulier. Elle a 3 contractions utérines en 10 minutes, chaque contraction utérine dure 40 secondes ; le col utérin est dilaté à 5 cm, les 2 pieds sont perçus dans l'aire de dilatation cervicale, la variété de présentation est en S.I.D.A. et le bassin est normal.\",\n       \"text\": \"Pour la cotation du score d'Apgar à 1 minute du nouveau-né, vous avez coté 2 pour la fréquence cardiaque et 1 pour chacun des autres paramètres. Ainsi, le total du score d'Apgar à 1 minute est : (Relever la bonne réponse parmi les propositions suivantes)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A:7\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B:5\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C:3\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D:4\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E:9\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"F:6\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"F. F:6\",\n       \"answerLetters\": [\n        \"F\"\n       ],\n       \"explanation\": \"Le score d'Apgar comporte 5 paramètres cotés de 0 à 2 (rythme cardiaque, respiration, tonus, réactivité, coloration) : 2 + 1 + 1 + 1 + 1 = 6.\\n\\nSource : COURS DE SOINS OBSTETRICAUX 2e année SF, Soins au nouveau-né, indice d'Apgar\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J6 (SF3)\",\n       \"sourceFile\": \"J6_Gyneco_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j6-sf3__39\",\n       \"num\": \"40\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"2ème CAS CLINIQUE. Vous avez reçu, ce jour, à 6 heures, dans la maternité rurale où vous exercez, Mme C.C.C. pour des contractions utérines sur grossesse à terme. Mme C.C.C. a 27 ans, 4ème geste, 3ème pare, sans antécédent particulier. Elle a 3 contractions utérines en 10 minutes, chaque contraction utérine dure 40 secondes ; le col utérin est dilaté à 5 cm, les 2 pieds sont perçus dans l'aire de dilatation cervicale, la variété de présentation est en S.I.D.A. et le bassin est normal.\",\n       \"text\": \"Après la fin de l'accouchement de Mme C.C.C., vous pensez qu'il y a une rupture utérine ; pour cela, vous décidez de lever ce doute en réalisant :(Parmi les propositions suivantes, relever ce geste approprié ou ces gestes appropriés)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A : Perfusion intraveineuse de 5 unités de syntocinon*(ocytocine)\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B : Délivrance artificielle\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C : Perfusion intraveineuse d'antibiotiques et de 5 unités de syntocinon*(ocytocine)\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D : Délivrance artificielle suivie de révision utérine\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E : Révision utérine\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"F : Révision utérine suivie de délivrance artificielle\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"E. E : Révision utérine\",\n       \"answerLetters\": [\n        \"E\"\n       ],\n       \"explanation\": \"Pour confirmer ou éliminer une rupture utérine après l'accouchement (délivrance déjà faite), on fait une révision utérine, qui explore le fond, les faces et les bords de l'utérus et contrôle son intégrité.\\n\\nSource : SONU L3, Délivrance artificielle et révision utérine (p. 49)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J6 (SF3)\",\n       \"sourceFile\": \"J6_Gyneco_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      }\n     ]\n    }\n   ]\n  }\n ]\n}";
